  name: "test",
  instructions: "test",
  model: openai("gpt-4o-mini"),
});

const workflow = createWorkflowChain({
  id: "test",
  input: z.string(),
  result: z.any(),
})
// @ts-ignore
.andAgent(({data}) => data, agent);

