import { Agent, createWorkflowChain } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import * as dotenv from "dotenv";
import * as fs from "fs";

dotenv.config();

async function main() {
  // 1. Create a Writer Agent that takes a topic and writes a short article.
  const writer = new Agent({
    name: "Writer",
    instructions: "You are a professional writer. Write a short article about the given topic. The output should be plain text.",
    model: openai("gpt-4o-mini"),
  });

  // 2. Create an Editor Agent that takes a drafted article and improves its grammar, clarity, and tone.
  const editor = new Agent({
    name: "Editor",
    instructions: "You are a professional editor. Improve the grammar, clarity, and tone of the provided article. Maintain the original meaning but enhance the quality. The output should be plain text.",
    model: openai("gpt-4o-mini"),
  });

  // 3. Create a workflow using createWorkflowChain that chains the Writer and Editor sequentially.
  const workflow = createWorkflowChain({
    id: "writer-editor-workflow",
    name: "Writer-Editor Workflow",
    purpose: "Draft and edit an article sequentially",
    input: z.string(),
    result: z.string(),
  })
    // @ts-ignore - andAgent signature can be tricky with plain text, but this is the intended way to chain agents
    .andAgent(({ data }) => data, writer, { id: "writer-step", schema: z.any() })
    // @ts-ignore
    .andAgent(({ data }) => data.content, editor, { id: "editor-step", schema: z.any() })
    .andThen({
      id: "finalize",
      execute: async ({ data }) => (data as any).content
    });

  const topic = "The Future of AI";
  console.log(`Running workflow for topic: "${topic}"...`);

  try {
    // 4. Run the workflow with the initial input text "The Future of AI".
    const execution = await workflow.run(topic);

    if (execution.status === "completed") {
      const finalOutput = execution.result;

      // 5. Write the final output string to /home/user/myproject/output.txt.
      const outputPath = "/home/user/myproject/output.txt";
      fs.writeFileSync(outputPath, finalOutput as string);
      console.log(`Workflow completed. Output saved to ${outputPath}`);
    } else {
      console.error(`Workflow ended with status: ${execution.status}`);
      if (execution.error) {
        console.error("Error:", execution.error);
      }
    }
  } catch (error) {
    console.error("Failed to execute workflow:", error);
  }

  // 6. index.ts must call process.exit(0) after writing output.txt.
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

